using System.IO;
using System.Collections.Generic;
using System.Linq;
using NeoCompose.Runtime.Json;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace NeoCompose.Tests
{
    /// <summary>
    /// Newtonsoft.Json round-trip coverage for <see cref="ProjectData"/>
    /// and the full IR tree rooted on <see cref="Member.getter"/>.
    ///
    /// Two fixtures back the suite:
    ///
    ///  - <c>synth-example.json</c> — generated by the TS-side dump
    ///    script (`scripts/dump-synth-export.ts`). Designed to exercise
    ///    every IR variant: list / dict literals, force-unwrap,
    ///    isCheck, callGetter, coalesce, where / count functions, both
    ///    arithmetic + boolean operations, and the four instruction
    ///    kinds (variable / if / return / throw, plus the bare
    ///    <c>return;</c> null-pointer case).
    ///  - <c>project-example.json</c> — a real-world export captured
    ///    from a live Neo-Compose authoring session.
    ///
    /// Tests load each fixture from
    /// <c>Packages/com.ryanbliss.neocompose/Tests/</c> (the canonical
    /// Unity Package Manager path for local-path references and
    /// registry installs alike) and pass the JSON through
    /// <see cref="JsonConvert.DeserializeObject{T}(string)"/>.
    /// </summary>
    public class ProjectExportRoundTripTests
    {
        private const string PackageRoot =
            "Packages/com.ryanbliss.neocompose/Tests";

        private static string LoadFixture(string fileName)
        {
            return File.ReadAllText(Path.Combine(PackageRoot, fileName));
        }

        private static ProjectData Deserialize(string json)
        {
            return JsonConvert.DeserializeObject<ProjectData>(json);
        }

        [Test]
        public void AnimationMemberMetadata_RoundTripsPartialFunctionRefAndUiBody()
        {
            const string classJson = @"{
  'id':'partial','projectId':'project','name':'Overrides','kind':7,
  'locked':true,'required':false,'isStatic':false,'accessModifierKind':'public',
  'classId':'target','partial':true,'createdAt':'x','updatedAt':'x'
}";
            var partial = (ClassMember)JsonConvert.DeserializeObject<Member>(classJson)!;
            Assert.AreEqual(true, partial.partial);

            const string genericJson = @"{
  'id':'generic-partial','projectId':'project','name':'Overrides','kind':21,
  'locked':true,'required':false,'isStatic':false,'accessModifierKind':'public',
  'genericParamId':'target-param','partial':true,'createdAt':'x','updatedAt':'x'
}";
            var generic = (GenericMember)JsonConvert.DeserializeObject<Member>(genericJson)!;
            Assert.AreEqual(true, generic.partial);

            const string functionRefJson = @"{
  'id':'action-ref','projectId':'project','name':'Action','kind':24,
  'locked':true,'required':true,'isStatic':false,'accessModifierKind':'public',
  'defaultValue':{'value':{'functionMemberId':'function-a'}},
  'createdAt':'x','updatedAt':'x'
}";
            var functionRef = (FunctionRefMember)JsonConvert.DeserializeObject<Member>(functionRefJson)!;
            Assert.AreEqual(24, (int)functionRef.kind);
            Assert.AreEqual("function-a", functionRef.defaultValue!.value!["functionMemberId"]);

            const string nsFunctionJson = @"{
  'id':'ui-function','projectId':'project','name':'OnFrame','kind':23,
  'locked':false,'required':false,'isStatic':false,'accessModifierKind':'public',
  'code':'return;','bodyMode':'ui','returnTypeInfo':{'type':'Void','required':true},
  'argumentTypes':[],'deferred':false,'createdAt':'x','updatedAt':'x',
  'uiAction':{'parameters':[],'instructions':[],'typeInfo':{'type':0,'required':true}},
  'action':{'parameters':[],'instructions':[],'typeInfo':{'type':0,'required':true}}
}";
            var nsFunction = (NSFunctionMember)JsonConvert.DeserializeObject<Member>(nsFunctionJson)!;
            Assert.AreEqual("ui", nsFunction.bodyMode);
            Assert.IsNotNull(nsFunction.uiAction);

            JObject serialized = JObject.Parse(JsonConvert.SerializeObject(nsFunction));
            Assert.AreEqual("ui", serialized.Value<string>("bodyMode"));
            Assert.IsNotNull(serialized["uiAction"]);

            const string placedChildJson = @"{
  'id':'placed-child','classId':'sprite-child','sourceValueId':'authored-child',
  'createdAt':'x','updatedAt':'x','value':{}
}";
            var placedChild = (ObjectMemberValue)JsonConvert
                .DeserializeObject<MemberValue>(placedChildJson)!;
            Assert.AreEqual("authored-child", placedChild.sourceValueId);
            JObject serializedChild = JObject.Parse(
                JsonConvert.SerializeObject(placedChild));
            Assert.AreEqual(
                "authored-child",
                serializedChild.Value<string>("sourceValueId"));
        }

        [Test]
        public void NSPropertySetter_RoundTripsAuthoredCodeCompiledIrAndWritability()
        {
            var typeInfo = new PrimitiveTypeInfo
            {
                type = MemberKind.Int,
                required = true,
            };
            var source = new NSPropertyMember
            {
                id = "property-with-setter",
                projectId = "project",
                name = "Score",
                kind = MemberKind.NSProperty,
                isStatic = true,
                accessModifierKind = "public",
                code = "return root.Save.Score;",
                returnTypeInfo = typeInfo,
                getter = new FunctionWithReturnType
                {
                    parameters = System.Array.Empty<Variable>(),
                    instructions = System.Array.Empty<Instruction>(),
                    typeInfo = typeInfo,
                },
                setterCode = "root.Save.Score = value;",
                setter = new FunctionWithReturnType
                {
                    parameters = System.Array.Empty<Variable>(),
                    instructions = new Instruction[]
                    {
                        new AssignInstruction
                        {
                            type = InstructionKind.Assign,
                            target = new WriteTarget
                            {
                                pointer = new ReferencePointer
                                {
                                    type = PointerKind.Reference,
                                    valueId = "score-value",
                                },
                                typeInfo = typeInfo,
                                writability = WritabilityKind.Setter,
                            },
                            operatorValue = "=",
                            pointer = new VariablePointer
                            {
                                type = PointerKind.Variable,
                                variableId = "__value__",
                            },
                        },
                    },
                    typeInfo = new PrimitiveTypeInfo
                    {
                        type = MemberKind.Null,
                        required = true,
                    },
                },
                createdAt = "x",
                updatedAt = "x",
            };

            string json = JsonConvert.SerializeObject(source);
            var roundTripped = (NSPropertyMember)JsonConvert
                .DeserializeObject<Member>(json)!;

            Assert.AreEqual(source.setterCode, roundTripped.setterCode);
            Assert.IsTrue(roundTripped.isStatic);
            Assert.IsNotNull(roundTripped.setter);
            var assign = (AssignInstruction)roundTripped.setter!.instructions[0];
            Assert.AreEqual(WritabilityKind.Setter, assign.target.writability);
            Assert.AreEqual("__value__", ((VariablePointer)assign.pointer).variableId);
        }

        [Test]
        public void WriteTarget_RuntimeWritabilityAndSchemaEightVocabularyRoundTrip()
        {
            var source = new WriteTarget
            {
                pointer = new ReferencePointer
                {
                    type = PointerKind.Reference,
                    valueId = "runtime-value",
                },
                typeInfo = new PrimitiveTypeInfo
                {
                    type = MemberKind.Int,
                    required = true,
                },
                writability = WritabilityKind.Runtime,
            };

            var roundTripped = JsonConvert.DeserializeObject<WriteTarget>(
                JsonConvert.SerializeObject(source))!;

            Assert.AreEqual("runtime", roundTripped.writability);
            Assert.AreEqual("immutable", WritabilityKind.Immutable);
            Assert.AreEqual("immutableToSaveLookup", WritabilityKind.ImmutableToSaveLookup);
            Assert.AreEqual("immutableToSessionLookup", WritabilityKind.ImmutableToSessionLookup);
        }

        /// <summary>
        /// P43 §1 — a computed member default carries source plus compiled IR
        /// and no baked <c>value</c>.
        /// </summary>
        [Test]
        public void MemberDefault_InitBodyRoundTrips()
        {
            const string json = @"{
  ""id"": ""member-loud"",
  ""projectId"": ""project"",
  ""name"": ""Loud"",
  ""kind"": 3,
  ""locked"": false,
  ""required"": true,
  ""isStatic"": false,
  ""accessModifierKind"": ""public"",
  ""defaultValue"": {
    ""init"": {
      ""code"": ""StaticFunc(\""bar\"")"",
      ""compiled"": {
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 3, ""required"": true }
      }
    }
  },
  ""createdAt"": ""x"",
  ""updatedAt"": ""x""
}";

            var member = (StringMember)JsonConvert.DeserializeObject<Member>(json)!;

            Assert.IsNotNull(member.defaultValue!.init);
            Assert.AreEqual("StaticFunc(\"bar\")", member.defaultValue.init!.code);
            Assert.AreEqual(3, member.defaultValue.init.compiled!.compilerRevision);
            Assert.IsNull(member.defaultValue.value);
            Assert.IsNull(member.defaultValue.classId);
        }

        /// <summary>
        /// P43 §1.1a — a stored value ROW may carry an initializer too, which
        /// is what keeps a literal list's entries addressable while each entry
        /// computes its own interior.
        /// </summary>
        [Test]
        public void MemberValueRow_InitBodyRoundTrips()
        {
            const string json = @"{
  ""id"": ""value-eyes-left"",
  ""projectId"": ""project"",
  ""init"": { ""code"": ""new EyePart(IsRight: false)"" },
  ""createdAt"": ""x"",
  ""updatedAt"": ""x""
}";

            var row = JsonConvert.DeserializeObject<MemberValue>(json)!;

            Assert.AreEqual("value-eyes-left", row.id);
            Assert.AreEqual("new EyePart(IsRight: false)", row.init!.code);
            Assert.IsNull(row.init.compiled);
        }

