            Assert.Throws<JsonSerializationException>(() =>
                JsonConvert.DeserializeObject<Pointer>(@"{
  ""type"": ""callFunction"",
  ""memberId"": ""member-function"",
  ""memberKey"": ""TakeDamage"",
  ""callSiteId"": ""call-3"",
  ""receiver"": { ""kind"": ""instance"", ""pointer"": { ""type"": ""reference"", ""valueId"": ""value"" } },
