        [Test]
        public void SynthFixture_NSGetterCompiledIR_DispatchesAllInstructionKinds()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));
            var score = (NSPropertyMember)export.members["member-score"];
            var getter = score.getter;
            Assert.IsNotNull(getter);
            Assert.IsNotEmpty(getter.instructions);

            // The synth fixture's getter walks: variable, variable, if
            // (with nested arithmetic + isCheck + force-unwrap +
            // coalesce + keyOf + listLiteral + where + count), and a
            // bare `return null;`.
            Assert.IsInstanceOf<VariableInstruction>(getter.instructions[0]);
            Assert.IsInstanceOf<VariableInstruction>(getter.instructions[1]);
            Assert.IsInstanceOf<IfInstruction>(getter.instructions[2]);
            Assert.IsInstanceOf<ReturnInstruction>(getter.instructions[3]);

            // The if-instruction's `else` field is renamed to
            // `elseInstructions` on the C# side via [JsonProperty].
            var ifInstr = (IfInstruction)getter.instructions[2];
            Assert.IsNotEmpty(ifInstr.branches);
            Assert.IsNotEmpty(ifInstr.elseInstructions);
            Assert.IsInstanceOf<ThrowInstruction>(ifInstr.elseInstructions[0]);

            // Bare `return;` → wire `pointer: null` → C# null.
            var returnInstr = (ReturnInstruction)getter.instructions[3];
            Assert.IsNull(returnInstr.pointer);
        }

